                    Location location = new Location(row, col);
                    Animal cheetah = new Cheetah(true, field, location);
                    animals.add(cheetah);
                }
                else if(rand.nextDouble() <= GAZELLE_CREATION_PROBABILITY) {
                    Location location = new Location(row, col);
                    Animal gazelle = new Gazelle(true, field, location);
                    animals.add(gazelle);
